{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a map of the ruined royal city.",
      "visual_description": "A windswept hilltop overlook at dusk; ink-stained coat flaring, a brass compass open in her palm, the broken skyline of the dead capital glittering below.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of a trap inside the city.",
      "visual_description": "Close-up of an oil lamp resting on the open map, its single flame-eye blinking, casting long warning shadows across painted streets.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin fox is wound up and sent ahead to scout.",
      "visual_description": "A small clockwork fox on cobblestones, key-wind tail mid-turn, blue glass eyes glowing as it slips past a fallen royal banner.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "Glass diver emerges from a cracked shop window.",
      "visual_description": "A figure in a clear diving helmet stepping out of a shattered windowpane like water, coat reflecting fractured neon and torchlight from the ruined avenue.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers beneath the castle gates.",
      "visual_description": "Towering iron gates choked with vines; Mara, the glass diver, the tin fox, and the lit oracle lamp huddled in a pool of green lantern light.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "An armored patrol marches past their hiding place.",
      "visual_description": "Mara and the glass diver pressed flat behind a toppled statue, the shadows of helmeted figures sweeping across the wall in lockstep.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "They find the sleeping tax collector slumped at a checkpoint.",
      "visual_description": "A booth piled with stamped papers; the official snoring on a ledger pillow, official seals stuck to his sleeves, key ring dangling from a limp hand.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Tin fox steals the keys without waking him.",
      "visual_description": "The clockwork fox balanced on the ledger, blue eyes narrowed, key ring delicately pinched between metal teeth as the official keeps snoring.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 9,
      "caption": "Frightened townspeople whisper rumors of a winged beast.",
      "visual_description": "Shadowed faces peering from boarded windows along a narrow alley, pointing toward distant smoke; Mara pauses, listening, lantern raised.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The oracle lamp insists they ignore the tower rumors.",
      "visual_description": "The lamp's flame-eye flares bright orange, illuminating Mara's tired face as a cursed tower looms on the horizon, crackling with violet lightning.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "Glass diver slips through a tall stained-glass window.",
      "visual_description": "A rippling pane of saints and serpents; the diver's coat dissolving into colored reflections as he passes inside the cathedral wing.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Inside, a magic door demands a true name.",
      "visual_description": "An iron door carved with shifting runes, glowing in the dark; the glass diver pressing a gloved palm to its surface as the oracle lamp hovers near.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "Mara unrolls a map that reveals a secret corridor.",
      "visual_description": "Candlelit chamber, parchment glowing where her compass needle touches it, ink lines redrawing themselves into a hidden passage behind the wall.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "They find the captive in a mirrored cell.",
      "visual_description": "A room of tall mirrors reflecting a small figure curled on the floor; the glass diver reaching one hand through a mirror's surface like still water.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "Tin fox triggers an alarm escaping the throne room.",
      "visual_description": "Dust shaking from chandeliers, faded royal banners trembling; the clockwork fox sprinting across a marble floor, key-tail spinning wildly.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols converge in the courtyard below.",
      "visual_description": "Aerial view of a torchlit plaza filling with marching shapes; the team crouched on a rooftop, the oracle lamp shielded under Mara's coat.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the long stone bridge at dawn.",
      "visual_description": "A cracked viaduct over a misty chasm, lanterns swinging, coats streaming behind; the oracle lamp's eye blazing like a headlamp leading the way.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far side, they look back at the burning city.",
      "visual_description": "Sunrise over a green hillside; the team silhouetted against the distant smoking skyline, Mara folding her map, tin fox at her boot, lamp dimming to a tired ember.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    }
  ]
}

